properties.query:
let detectionWindow = 1h;   // must equal queryFrequency
let baseline = 14d;         // must stay <= queryPeriod
// Delinea exposes no in-band sensitivity flag - tags and analyticData are null on every
// secret event - so value is inferred from the secret name and its folder. Secret Server
// permissions are inherited from folder placement, which makes containerName the strongest
// tiering signal, and it exists only inside notes: top-level target.containerName is null.
//
// TUNING 1 of 2: common high-value naming conventions, matched as a case insensitive
// substring against both the secret name and its folder. Trim groups that are noisy in
// your tenant; add cloud and CI terms (azure, aws, gcp, jenkins, ansible, terraform) only
// if those secrets are genuinely privileged, as they match broadly.
let sensitivePattern = @"(?i)admin|administrator|\broot\b|sudo|superuser|breakglass|break.?glass|emergency|privileged|\bpriv\b|\bda\b|\bea\b|domain.?admin|enterprise.?admin|\bsa[-_]|\bsvc[-_]|service.?account|\bprod\b|production|\bprd\b|backup|restore|disaster|\bdr\b|domain.?controller|\bdc\d|firewall|router|esxi|vcenter|hypervisor|\bsql\b|mysql|mssql|postgres|oracle|mongo|\bdba\b|\bkey\b|api.?key|keystore|vault|token|credential|password|passwd|\bpwd\b|cert\b|certificate|\bpki\b|ssh|rdp|winrm";
// TUNING 2 of 2: tenant specific names, filled in at deployment time. Exact match, case
// insensitive - use sensitivePattern above for substring matching. Leave empty if unused.
let customSecretNames = dynamic([]);
//   e.g. dynamic(["Break Glass Account", "ESXi root", "SAP_PROD_ADMIN"]);
let customFolders = dynamic([]);
//   e.g. dynamic(["Tier 0", "Domain Admins", "Production Databases"]);
let access =
    DelineaAuditEvents_CL
    | where TimeGenerated > ago(baseline)
    | extend IngestedAt = ingestion_time()
    | extend d = parse_json(RawData)
    | where tostring(d.eventType.name) == "Delinea.Vault.Secret.Viewed"
    // notes is a JSON document carried as a string - same idiom as
    // Workbooks/DelineaSecretServerVaultActivity.json
    | extend n = parse_json(tostring(d.notes))
    | extend Actor = tostring(coalesce(d.actor.name, d.actor.email, d.actor.displayName)),
             ActorEmail = tostring(d.actor.email),
             SecretKey = tostring(coalesce(d.target.id, d.target.platformId, n.itemId)),
             // Trimmed because these become entity identifiers - Delinea returns names
             // such as '10.60.25.30 MYSQL ' with trailing whitespace.
             SecretName = trim(@'\s', coalesce(tostring(d.target.displayName), tostring(d.target.name),
                                   tostring(n.itemNameForDisplay), tostring(n.itemName), SecretId)),
             Folder = trim(@'\s', tostring(n.containerName)),
             Details = tostring(n.eventDetails),
             RawSrcIP = tostring(coalesce(d.source.host.network.ipAddress, n.ipAddress))
    // eventDetails is free text: " Account Name: qa-e2e-target  Target Server: 10.60.25.51 "
    | extend AccountName = extract(@'Account Name:\s*(.*?)\s*(?:Target Server:|$)', 1, Details),
             TargetServer = extract(@'Target Server:\s*(.*?)\s*$', 1, Details)
    | extend SrcIP = iff(RawSrcIP in ("", "0.0.0.0"), "", RawSrcIP)
    | where isnotempty(Actor) and isnotempty(SecretKey)
    // To rely on the custom lists alone, delete the two 'matches regex' clauses - do not
    // blank sensitivePattern, an empty regex matches every row.
    | where SecretName matches regex sensitivePattern
         or Folder matches regex sensitivePattern
         or SecretName in~ (customSecretNames)
         or Folder in~ (customFolders);
// Batch by ingestion time so a late arriving event is still evaluated exactly once.
let priorAccess = access | where IngestedAt <= ago(detectionWindow) | distinct Actor, SecretKey;
access
| where IngestedAt > ago(detectionWindow)
| join kind=leftanti priorAccess on Actor, SecretKey
| summarize FirstAccess = min(TimeGenerated), LastAccess = max(TimeGenerated), Accesses = count(),
            SecretName = take_any(SecretName), Folder = take_any(Folder),
            ActorEmail = take_anyif(ActorEmail, isnotempty(ActorEmail)),
            AccountNames = make_set_if(AccountName, isnotempty(AccountName), 10),
            TargetServers = make_set_if(TargetServer, isnotempty(TargetServer), 10),
            TargetServer = take_anyif(TargetServer, isnotempty(TargetServer)),
            SourceIPs = make_set_if(SrcIP, isnotempty(SrcIP), 20),
            SrcIP = take_anyif(SrcIP, isnotempty(SrcIP))
        by Actor, SecretKey
// 'Target Server' is reported as either an address or a hostname, so each row feeds
// whichever entity fits and blanks the other. Sentinel skips empty entity values.
| extend TargetIsIp = isnotnull(parse_ipv4(TargetServer)) or isnotnull(parse_ipv6(TargetServer))
| extend TargetIP = iff(TargetIsIp, TargetServer, ""),
         TargetHost = iff(TargetIsIp, "", TargetServer)
| project FirstAccess, LastAccess, Actor, ActorEmail, SecretKey, SecretName, Folder,
          AccountNames, TargetServers, TargetHost, TargetIP, Accesses, SourceIPs, SrcIP
| sort by FirstAccess desc
